mod solution;

fn main() {
    let cases = [
    (r#"edges=(0,1),(0,2),(1,3),(2,4)"#, r#"0,1,3,2,4"#),
    (r#"edges=(0,2),(0,1)"#, r#"0,1,2"#),
    (r#"
edges=(0,2),(0,1)
"#, r#"0,1,2"#),
    (r#"  
edges=(0,1),(0,2),(1,3),(2,4)
  "#, r#"0,1,3,2,4"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS graph-dfs");
}
